void readSingleImageFrame(MagickCore::Image *image, MagickCore::ExceptionInfo *exceptionInfo) {
  if (image != (MagickCore::Image *) NULL) {
    if (image->next != (MagickCore::Image *) NULL) {
      MagickCore::Image *nextImage = image->next;
      MagickCore::Image *lastImage = image;

      while (lastImage->next != (MagickCore::Image *) NULL) {
        lastImage = lastImage->next;
      }

      while (nextImage != (MagickCore::Image *) NULL) {
        MagickCore::Image *temp = nextImage;
        nextImage = nextImage->next;
        ImageDestroy(temp);
      }

      lastImage->next = (MagickCore::Image *) NULL;
    }
  }

  if (exceptionInfo != (MagickCore::ExceptionInfo *) NULL) {
    if (GetExceptionType(exceptionInfo) == UndefinedException) {
      if (image == (MagickCore::Image *) NULL) {
        exceptionInfo = DestroyExceptionInfo(exceptionInfo);
        if (!IsEventLogging())
          (void) fprintf(stderr, "Warning: Unable to read image.\n");
      }
    }
  }

  ThrowImageException(exceptionInfo);
}

