        if (!quiet) {
            (void) fprintf(stderr, "warning: no image to read\n");
        }
    }

    ThrowBinaryBlobException(OptionError, "UnableToReadImage", image);
}

void readSingleImageFrame(MagickCore::Image *image, MagickCore::ExceptionInfo *exceptionInfo) {
  if (image && image->scene != 0) {
    image = CloneImage(image, image->width, image->height, MagickFalse, exceptionInfo);
    if (image && image->next != NULL) {
      MagickCore::Image *next = image->next;
      while (next) {
        MagickCore::Image *current = next;
        next = current->next;
        current->next = NULL;
        DestroyImage(current);
      }
    }
  }

  if (image != NULL) {
    ReplaceImage(&image, image);
  }

  if (exceptionInfo->severity == UndefinedException && image == NULL) {
    DestroyExceptionInfo(exceptionInfo);
    if (!quiet_mode) {
      (void) ThrowMagickException(exceptionInfo, GetMagickModule(), WarningError, "NullImage", "`NULL' image");
    }
  }

  ThrowImageException(image, MissingDelegateError, "NoImageBlob");
}

